
import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card } from '@/components/ui/card';
import { useToast } from '@/hooks/use-toast';
import type { User } from '@/lib/types';
import Image from 'next/image';

interface LoginPageProps {
  // onSuccess receives the minimal login response from the server
  onSuccess: (data: { role: 'parent' | 'child'; username: string }) => void;
}


// Dummy users list for demo; replace with real user DB or API
const DEMO_USERS: User[] = [
  {
    email: 'parent@example.com',
    username: 'parent',
    name: 'Parent User',
    role: 'parent',
    age: 40,
    relationships: {},
    likings: [],
    dislikings: [],
  },
  {
    email: 'child@example.com',
    username: 'child',
    name: 'Child User',
    role: 'child',
    age: 12,
    relationships: {},
    likings: [],
    dislikings: [],
  },
];

export function LoginPage({ onSuccess }: LoginPageProps) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const router = useRouter();

  // Animation: simple SVG for the "bridge" and pulsing sparks
  function AnimatedConnection() {
    return (
      <svg width="320" height="80" viewBox="0 0 320 80" fill="none" xmlns="http://www.w3.org/2000/svg" className="mx-auto mb-4">
        {/* Parent spark */}
        <circle cx="40" cy="40" r="12">
          <animate attributeName="r" values="12;16;12" dur="2.5s" repeatCount="indefinite" />
          <animate attributeName="opacity" values="1;0.7;1" dur="2.5s" repeatCount="indefinite" />
        </circle>
        <circle cx="40" cy="40" r="12" fill="#4A908C" opacity="0.7" />
        {/* Child spark */}
        <circle cx="280" cy="40" r="12">
          <animate attributeName="r" values="12;16;12" dur="2.5s" repeatCount="indefinite" />
          <animate attributeName="opacity" values="1;0.7;1" dur="2.5s" repeatCount="indefinite" />
        </circle>
        <circle cx="280" cy="40" r="12" fill="#50A6D1" opacity="0.7" />
        {/* Animated bridge (organic line) */}
        <path id="bridge" d="M 52 40 Q 160 10 268 40" stroke="#FFC300" strokeWidth="6" fill="none">
          <animate attributeName="d" values="M 52 40 Q 160 10 268 40;M 52 40 Q 160 70 268 40;M 52 40 Q 160 10 268 40" dur="5s" repeatCount="indefinite" />
        </path>
        <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
          <feGaussianBlur stdDeviation="4" result="coloredBlur" />
          <feMerge>
            <feMergeNode in="coloredBlur" />
            <feMergeNode in="SourceGraphic" />
          </feMerge>
        </filter>
        <path d="M 52 40 Q 160 10 268 40" stroke="#FFC300" strokeWidth="6" fill="none" filter="url(#glow)" opacity="0.5" />
      </svg>
    );
  }

  // Logo SVG (Kindred tree, simple)
  function Logo() {
    return (
      <div className="flex justify-center mt-8 mb-2">
        <svg width="64" height="64" viewBox="0 0 64 64" fill="none" xmlns="http://www.w3.org/2000/svg">
          <circle cx="32" cy="32" r="30" stroke="#333" strokeWidth="3" fill="none" />
          <path d="M32 48 Q32 36 24 28 Q20 24 24 20 Q28 16 32 24 Q36 16 40 20 Q44 24 40 28 Q32 36 32 48" stroke="#333" strokeWidth="3" fill="none" />
          <circle cx="24" cy="20" r="2.5" fill="#333" />
          <circle cx="40" cy="20" r="2.5" fill="#333" />
        </svg>
      </div>
    );
  }

  // Handle login: check email only
  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    // Find user by email (case-insensitive)
    const user = DEMO_USERS.find(u => u.email.toLowerCase() === email.trim().toLowerCase());
    if (!user) {
      setError('No account found for this email.');
      return;
    }
    // Success: set active user and route
    onSuccess({ role: user.role as 'parent' | 'child', username: user.username });
    if (user.role === 'parent') {
      router.push('/parent');
    } else {
      router.push('/child');
    }
  };

  // Register navigation
  const handleRegister = (e: React.MouseEvent) => {
    e.preventDefault();
    router.push('/register');
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-between" style={{ background: '#F8F7F4' }}>
      {/* Logo */}
      <Logo />

      {/* Animated Connection */}
      <div className="flex flex-col items-center w-full">
        <AnimatedConnection />
        {/* Tagline */}
        <div className="text-center mb-6">
          <div className="text-2xl md:text-3xl font-semibold mb-1" style={{ color: '#333' }}>
            Nurture your connection.
          </div>
          <div className="text-base md:text-lg" style={{ color: '#333', opacity: 0.7 }}>
            Your gentle, helping hand for a closer family.
          </div>
        </div>
      </div>

      {/* Action Card */}
      <div className="w-full flex flex-col items-center mb-12">
        <Card className="w-full max-w-md p-8 rounded-3xl shadow-lg border-0 bg-white/95" style={{ boxShadow: '0 4px 24px 0 rgba(51,51,51,0.06)' }}>
          <h2 className="text-xl font-bold text-center mb-6" style={{ color: '#333' }}>Welcome</h2>
          <form onSubmit={handleLogin} className="space-y-5">
            <div>
              <label htmlFor="email" className="block text-sm font-medium mb-1" style={{ color: '#333' }}>
                Email or Username
              </label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">
                  <svg width="18" height="18" fill="none" viewBox="0 0 24 24"><path d="M12 12c2.7 0 5-2.3 5-5s-2.3-5-5-5-5 2.3-5 5 2.3 5 5 5zm0 2c-3.3 0-10 1.7-10 5v3h20v-3c0-3.3-6.7-5-10-5z" fill="#B0B0B0"/></svg>
                </span>
                <Input
                  id="email"
                  type="text"
                  placeholder="Enter your email or username"
                  value={email}
                  onChange={e => setEmail(e.target.value)}
                  required
                  className="w-full pl-10 py-2 bg-[#F8F7F4] border-0 border-b-2 border-[#E0DFDB] focus:border-[#4A908C] rounded-none focus:bg-white transition"
                  style={{ boxShadow: 'none' }}
                />
              </div>
            </div>
            <div>
              <label htmlFor="password" className="block text-sm font-medium mb-1" style={{ color: '#333' }}>
                Password
              </label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400">
                  <svg width="18" height="18" fill="none" viewBox="0 0 24 24"><path d="M12 17a2 2 0 1 0 0-4 2 2 0 0 0 0 4zm6-7V7a6 6 0 1 0-12 0v3a2 2 0 0 0-2 2v7a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7a2 2 0 0 0-2-2zm-8-3a4 4 0 1 1 8 0v3H8V7z" fill="#B0B0B0"/></svg>
                </span>
                <Input
                  id="password"
                  type="password"
                  placeholder="Enter your password"
                  value={password}
                  onChange={e => setPassword(e.target.value)}
                  required
                  className="w-full pl-10 py-2 bg-[#F8F7F4] border-0 border-b-2 border-[#E0DFDB] focus:border-[#4A908C] rounded-none focus:bg-white transition"
                  style={{ boxShadow: 'none' }}
                />
              </div>
            </div>
            {error && (
              <div className="text-red-500 text-sm text-center">{error}</div>
            )}
            <Button
              type="submit"
              className="w-full py-3 rounded-full text-lg font-bold shadow-none border-0"
              style={{ background: '#FFC300', color: '#333', boxShadow: '0 2px 8px 0 rgba(255,195,0,0.08)' }}
            >
              Log In
            </Button>
          </form>
          <div className="mt-4 text-center text-base">
            First time here?{' '}
            <button
              className="font-bold"
              style={{ color: '#4A908C', background: 'none', border: 'none', cursor: 'pointer' }}
              onClick={handleRegister}
            >
              Create an account
            </button>
          </div>
        </Card>
      </div>
    </div>
  );
}